    'Gastronomia: del mar al plato3': {
        es: 'Descripción: Plato inspirado en la pureza del mar Caribe, elaborado con langosta espinosa de La Guajira y una salsa de leche de coco y maracuyá. Combina lo salado del mar con lo dulce tropical, logrando un equilibrio exótico y elegante.',
        en: 'Description: A dish inspired by the purity of the Caribbean Sea, made with spiny lobster from La Guajira and a coconut milk and passion fruit sauce. It combines the saltiness of the sea with the sweetness of the tropics, achieving an exotic and elegant balance.',
        fr: 'Description : Un plat inspiré par la pureté de la mer des Caraïbes, élaboré à partir de langoustines de La Guajira et dune sauce au lait de coco et au fruit de la passion. Il allie la salinité de la mer à la douceur des tropiques, pour un équilibre exotique et raffiné.'
    },

    'Gastronomia: del mar al plato4': {
        es: 'Inspiración: Representa la unión entre el mar y el trópico colombiano, resaltando los contrastes dulces y salados de la costa.',
        en: 'Inspiration: It represents the union between the sea and the Colombian tropics, highlighting the sweet and salty contrasts of the coast.',
        fr: 'Inspiration : Elle représente lunion entre la mer et les tropiques colombiens, mettant en lumière les contrastes sucrés et salés de la côte.'
    },

    'Gastronomia: del mar al plato5': {
        es: 'Encanto del Manglar',
        en: 'Charm of the Mangrove',
        fr: 'Le charme de la mangrove'
    },

    'Gastronomia: del mar al plato6': {
        es: 'Descripción: Cazuela cremosa elaborada con jaibas, chipichipis y camarones, cocinados en un sofrito costeño con ají dulce y leche de coco. Evoca los aromas de los manglares del golfo de Morrosquillo.',
        en: 'Description: A creamy casserole made with crabs, clams, and shrimp, cooked in a coastal-style sofrito with sweet chili peppers and coconut milk. It evokes the aromas of the mangroves of the Gulf of Morrosquillo.',
        fr: 'Description : Un gratin onctueux de crabes, de palourdes et de crevettes, mijoté dans un sofrito à la mode côtière, relevé de piments doux et de lait de coco. Il évoque les arômes des mangroves du golfe de Morrosquillo.'
    },

    'Gastronomia: del mar al plato7': {
        es: 'Inspiración: Homenaje a los manglares de Sucre y Córdoba, cuna de vida marina y tradición culinaria.',
        en: 'Inspiration: A tribute to the mangroves of Sucre and Córdoba, cradle of marine life and culinary tradition.',
        fr: 'Inspiration : Un hommage aux mangroves de Sucre et de Cordoue, berceau de la vie marine et de la tradition culinaire.'
    },

    'Gastronomia: del mar al plato8': {
        es: 'Sabor del Río al Mar',
        en: 'Taste of the River to the Sea',
        fr: 'Goûtez à la rivière jusquà la mer'
    },

    'Gastronomia: del mar al plato9': {
        es: 'Descripción: Fusión entre el agua dulce y salada: róbalo del Magdalena con una costra de jaiba y salsa de tamarindo y coco. Simboliza el encuentro entre los ríos y el mar Caribe.',
        en: 'Description: A fusion of fresh and salt water: Magdalena River snook with a crab crust and tamarind and coconut sauce. It symbolizes the meeting of rivers and the Caribbean Sea.',
        fr: 'Description : Fusion deau douce et deau salée : un snook du fleuve Magdalena en croûte de crabe, accompagné dune sauce au tamarin et à la noix de coco. Il symbolise la rencontre des fleuves et de la mer des Caraïbes.'
    },

    'Gastronomia: del mar al plato10': {
        es: 'Inspiración: Representa la transición entre la pesca fluvial y marina, típica del Magdalena y Atlántico',
        en: 'Inspiration: It represents the transition between river and marine fishing, typical of the Magdalena and Atlantic regions.',
        fr: 'Inspiration : Elle représente la transition entre la pêche fluviale et la pêche maritime, typique des régions du Magdalena et de lAtlantique.'
    },

    'Gastronomia: del mar al plato11': {
        es: 'Mar y Sabor Caribeño',
        en: 'Sea and Caribbean Flavor',
        fr: 'Saveurs marines et caribéennes'
    },

    'Gastronomia: del mar al plato12': {
        es: 'Descripción general: Mar y Sabor Caribeño” es una fusión de sabores del Caribe colombiano, que combina la frescura del camarón rosado de La Guajira, la suavidad del pescado róbalo del Magdalena y el toque exótico del chipichipi de Sucre.<br>Su preparación rinde homenaje a la pesca artesanal y a la cocina tradicional costera, integrando ingredientes autóctonos como el coco, el plátano y el ají dulce.',
        en: 'Overview: “Sea and Caribbean Flavor” is a fusion of flavors from the Colombian Caribbean, combining the freshness of pink shrimp from La Guajira, the tenderness of snook from Magdalena, and the exotic touch of chipichipi clams from Sucre. Its preparation pays homage to artisanal fishing and traditional coastal cuisine, incorporating native ingredients such as coconut, plantain, and sweet pepper.',
        fr: 'Présentation : « Saveurs de la mer et des Caraïbes » est une fusion de saveurs des Caraïbes colombiennes, alliant la fraîcheur des crevettes roses de La Guajira, la tendreté du snook de Magdalena et la touche exotique des palourdes chipichipi de Sucre. Sa préparation rend hommage à la pêche artisanale et à la cuisine côtière traditionnelle, en intégrant des ingrédients locaux tels que la noix de coco, la banane plantain et le poivron doux.'
    },

    'Gastronomia: del mar al plato13': {
        es: 'Inspiración cultural: Este plato representa la diversidad marina del Caribe colombiano: Los camarones de La Guajira, símbolo de abundancia. El róbalo del Magdalena, reflejo del equilibrio entre río y mar. El chipichipi de Sucre, emblema de la cocina costera, La mezcla de coco, ají dulce y mariscos celebra la identidad culinaria afrocaribeña e indígena que caracteriza a toda la región.',
        en: 'Cultural inspiration: This dish represents the marine diversity of the Colombian Caribbean: Shrimp from La Guajira, a symbol of abundance; sea bass from the Magdalena River, reflecting the balance between river and sea; chipichipi from Sucre, an emblem of coastal cuisine; and the blend of coconut, sweet pepper, and seafood, celebrating the Afro-Caribbean and Indigenous culinary identity that characterizes the entire region.',
        fr: 'Inspiration culturelle : Ce plat représente la diversité marine des Caraïbes colombiennes : les crevettes de La Guajira, symbole d’abondance ; le bar du fleuve Magdalena, reflétant l’équilibre entre fleuve et mer ; les chipichipi de Sucre, emblème de la cuisine côtière ; et le mélange de noix de coco, de poivron doux et de fruits de mer, célébrant l’identité culinaire afro-caribéenne et indigène qui caractérise toute la région.'
    },

