// Función para cambiar el idioma
function changeLang(lang, text) {
    // Actualizar todos los elementos con data-translate
    document.querySelectorAll('[data-translate]').forEach(element => {
        const key = element.getAttribute('data-translate');
        if (translations[key] && translations[key][lang]) {
            element.textContent = translations[key][lang];
        }
    });

    // Actualizar el botón del idioma actual
    const currentLangBtn = document.getElementById('currentLang');
    if (currentLangBtn) {
        currentLangBtn.innerHTML = text + ' ▼';
    }

    // Guardar preferencia en localStorage
    localStorage.setItem('preferred-language', lang);
    localStorage.setItem('preferred-language-text', text);

    // Cerrar el dropdown
    const dropdownMenu = document.getElementById('dropdownMenu');
    if (dropdownMenu) {
        dropdownMenu.classList.remove('show');
    }

    // Mostrar notificación
    showLanguageNotification(text);
}

// Función para mostrar notificación de cambio de idioma
function showLanguageNotification(langText) {
    let notification = document.getElementById('lang-notification');
    
    if (!notification) {
        notification = document.createElement('div');
        notification.id = 'lang-notification';
        notification.className = 'lang-notification';
        document.body.appendChild(notification);
    }
    
    const messages = {
        '🇪🇸 Español': '🌐 Idioma cambiado a: Español',
        '🇬🇧 English': '🌐 Language changed to: English',
        '🇫🇷 Français': '🌐 Langue changée en: Français'
    };
    
    notification.textContent = messages[langText] || langText;
    notification.style.display = 'block';
    notification.style.animation = 'slideInRight 0.4s ease-out';
    
    setTimeout(() => {
        notification.style.animation = 'slideOutRight 0.4s ease-out';
        setTimeout(() => {
            notification.style.display = 'none';
        }, 400);
    }, 3000);
}

// Inicializar idioma al cargar la página
document.addEventListener('DOMContentLoaded', function() {
    const savedLanguage = localStorage.getItem('preferred-language') || 'es';
    const savedLanguageText = localStorage.getItem('preferred-language-text') || '🇪🇸 Español';
    
    changeLang(savedLanguage, savedLanguageText);
});

// Variable global para el idioma actual
let currentLanguage = 'es';

// Función principal de cambio de idioma
function changeLanguage(lang) {
    currentLanguage = lang;
    
    // Guardar preferencia en localStorage
    localStorage.setItem('preferredLanguage', lang);
    
    // Aplicar traducciones
    applyTranslations(lang);
    
    // Actualizar botones activos
    updateActiveButton(lang);
    
    // Mostrar notificación
    showNotification(lang);
}

// Aplicar todas las traducciones
function applyTranslations(lang) {
    // Traducir elementos con data-translate
    document.querySelectorAll('[data-translate]').forEach(element => {
        const key = element.getAttribute('data-translate');
        if (translations[key] && translations[key][lang]) {
            element.textContent = translations[key][lang];
        }
    });
}

// Actualizar botón activo
function updateActiveButton(lang) {
    document.querySelectorAll('.lang-btn').forEach(btn => {
        btn.classList.remove('active');
    });
    
    const langNames = {
        es: '🇪🇸 Español',
        en: '🇬🇧 English',
        fr: '🇫🇷 Français'
    };
    
    document.querySelectorAll('.lang-btn').forEach(btn => {
        if (btn.textContent.includes(langNames[lang].split(' ')[1])) {
            btn.classList.add('active');
        }
    });
}

// Mostrar notificación de cambio
function showNotification(lang) {
    const messages = {
        es: '✓ Idioma cambiado a Español',
        en: '✓ Language changed to English',
        fr: '✓ Langue changée en Français'
    };
    
    // Crear o reutilizar notificación
    let notification = document.getElementById('lang-notification');
    if (!notification) {
        notification = document.createElement('div');
        notification.id = 'lang-notification';
        notification.className = 'lang-notification';
        document.body.appendChild(notification);
    }
    
    notification.textContent = messages[lang];
    notification.classList.add('show');
    
    // Ocultar después de 3 segundos
    setTimeout(() => {
        notification.classList.remove('show');
    }, 3000);
}

// Cargar idioma guardado al iniciar
document.addEventListener('DOMContentLoaded', () => {
    const savedLanguage = localStorage.getItem('preferredLanguage') || 'es';
    changeLanguage(savedLanguage);
});